package com.gomgomapps.math.core;
import org.junit.Test;import static org.junit.Assert.*;import java.util.*;
public class CalculationOrderTest {
 @Test public void earlySubtractionPracticeIncludesBothComparisonOutcomes(){Generator g=new Generator(new Random(122));List<String> recent=new ArrayList<>();Set<String> results=new HashSet<>();for(int i=0;i<20;i++){Question q=g.next(CalculationOrder.SUB,recent,true,GlobalCurriculum.limits("england-primary-2021-v1",CalculationOrder.SUB,2));recent.add(q.signature());int[] v=CalculationOrder.read(q);results.add(v[0]==v[1]?"equal":"larger");}assertEquals(Set.of("equal","larger"),results);}
 @Test public void freshFiniteConditionsAndBothDomains(){for(String id:List.of(CalculationOrder.ADD,CalculationOrder.SUB)){Generator generator=new Generator(new Random(122));var limits=GlobalCurriculum.limits("england-primary-2021-v1",id,2);List<String> recent=new ArrayList<>();Set<String> outcomes=new HashSet<>();for(int i=0;i<231;i++){Question q=generator.next(id,recent,true,limits);assertFalse(recent.contains(q.signature()));recent.add(q.signature());int[] v=CalculationOrder.read(q);assertNotNull(v);boolean add=id.equals(CalculationOrder.ADD);List<String> expected=add?List.of(""+(v[0]+v[1]),""+(v[1]+v[0])):List.of(v[0]>v[1]?"larger":"fits");outcomes.add(expected.get(0));q.answers=add?new String[]{"bad","bad"}:new String[]{"bad"};assertTrue(new Checker().check(q,List.of(),expected).correct());HelpPlan plan=HelpPlan.forQuestion(q);assertFalse(plan.canTransfer());assertEquals(add?4:3,plan.size());if(add){assertTrue(q.choices.isEmpty());assertEquals(1,new Checker().check(q,List.of(),List.of(expected.get(0),"99")).index);}else{assertEquals(Set.of("fits","larger"),new HashSet<>(q.choices));assertFalse(new Checker().check(q,List.of(),List.of(expected.get(0).equals("fits")?"larger":"fits")).correct());}}assertEquals(id.equals(CalculationOrder.ADD)?21:2,outcomes.size());assertEquals(recent.get(0),generator.next(id,recent,false,limits).signature());}Learning.Profile p=new Learning.Profile();GlobalCurriculum.chooseCountry(p,"GB");GlobalCurriculum.choosePack(p,"england-primary-2021-v1");assertTrue(GlobalCurriculum.pack(p).inGrade(CalculationOrder.ADD,2));assertTrue(GlobalCurriculum.pack(p).inGrade(CalculationOrder.SUB,2));}
 @Test public void zeroEqualAndInvalidSwap(){for(int[] pair:new int[][]{{0,0},{20,0},{10,10},{0,20}}){Question q=CalculationOrder.make(CalculationOrder.ADD,pair[0],pair[1]);assertTrue(new Checker().check(q,List.of(),List.of(""+(pair[0]+pair[1]),""+(pair[0]+pair[1]))).correct());}for(int[] pair:new int[][]{{0,0},{20,0},{20,20},{13,7}}){Question q=CalculationOrder.make(CalculationOrder.SUB,pair[0],pair[1]);assertTrue(new Checker().check(q,List.of(),List.of(pair[0]==pair[1]?"fits":"larger")).correct());HelpPlan plan=HelpPlan.forQuestion(q);assertTrue(plan.step(0).accepts(""+pair[1]));assertTrue(plan.step(1).accepts(""+pair[0]));}Question malformed=CalculationOrder.make(CalculationOrder.ADD,4,6);malformed.prompt=CalculationOrder.ADD_PROMPT+"\n4 + 6\n6 + 7";assertNull(CalculationOrder.read(malformed));assertEquals(Checker.Status.INPUT_NEEDED,new Checker().check(malformed,List.of(),List.of("10","13")).status);try{CalculationOrder.make(CalculationOrder.SUB,0,1);fail();}catch(IllegalArgumentException expected){}}
}
